/** June-origin standalone AMD: H2 FY2026 followed by full fiscal years. */
import {incrementalRecord} from './incremental-registry.js';
const finite=x=>typeof x==='number'&&Number.isFinite(x);
const days=(a,b)=>(Date.parse(b+'T00:00:00Z')-Date.parse(a+'T00:00:00Z'))/86400000;
export function amdFiscalEnd(y){const d=new Date(Date.UTC(y,11,31));d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+1)%7);return d.toISOString().slice(0,10);}
export function selectedAmdCase(d){const r=incrementalRecord(d?.ticker);if(r?.bridge.type!=='amd-ev-only-v3')return null;return d.selectedIncrementalScenario?r.alternatives.find(x=>x.name===d.selectedIncrementalScenario)?.annualCase:r.annualCase;}
export function amdOperatingIssues(d){if(d?.ticker!=='AMD')return [];const c=selectedAmdCase(d);if(!c)return ['AMD requires its reviewed dated standalone case.'];return d.annual?.some((r,i)=>r.period!==(i?`FY${2026+i}`:'H2 FY2026'))?['AMD retains H2 FY2026 then exact fiscal-year labels; restore the reviewed case before changing its period structure.']:[];}
export function amdAnnualFunding(d,index,row=d.annual[index]){
 const p=selectedAmdCase(d)?.amdFundingPolicy;if(!p)throw Error('AMD requires its reviewed dated standalone case.');
 const fullFiscalRevenue=row.revenue+(index===0?p.h1ActualRevenue:0),prior=index===0?d.anchor.revenue:d.annual[index-1].revenue+(index===1?p.h1ActualRevenue:0),growth=fullFiscalRevenue/prior-1,delta=Math.max(0,fullFiscalRevenue-prior),physicalNetCapex=row.revenue*(p.capex[Math.min(index,9)]-p.depreciation[Math.min(index,9)]),incrementalNWC=delta*p.nwc,directFundingFloor=physicalNetCapex+incrementalNWC,nopat=row.revenue*row.margin-Math.max(0,row.revenue*row.margin)*row.taxRate,fade=Math.max(0,Math.min(1,(index-4)/5)),additionalEconomicReserve=Math.max(0,nopat*Math.max(0,growth)/d.terminal.roic-directFundingFloor)*fade,fixedOpeningFunding=index===0?421:0,requiredInvestment=directFundingFloor+additionalEconomicReserve+fixedOpeningFunding,reinvestment=Math.max(row.reinvestment,requiredInvestment);
 return {fullFiscalRevenue,growth,physicalNetCapex,incrementalNWC,directFundingFloor,additionalEconomicReserve,fixedOpeningFunding,requiredInvestment,enteredReinvestment:row.reinvestment,investmentFloorTopUp:reinvestment-row.reinvestment,reinvestment,normalizedOperatingReinvestment:reinvestment-fixedOpeningFunding};
}
export function calculateAmdOperating(d){
 const issues=amdOperatingIssues(d);if(issues.length)throw Error(issues.join(' '));let previousEnd=d.discountOrigin,discount=1,pv=0,cumulative=0,trough=0;
 const rows=d.annual.map((r,index)=>{const funding=amdAnnualFunding(d,index,r),periodEnd=amdFiscalEnd(2026+index),durationYears=days(previousEnd,periodEnd)/365.25,yearsFromOrigin=days(d.discountOrigin,periodEnd)/365.25,ebit=r.revenue*r.margin,tax=Math.max(0,ebit)*r.taxRate,nopat=ebit-tax,fcff=nopat-funding.reinvestment;discount*=(1+r.wacc)**durationYears;const presentValue=fcff/discount;pv+=presentValue;cumulative+=fcff;trough=Math.min(trough,cumulative);previousEnd=periodEnd;if(![...Object.values(funding),ebit,tax,nopat,fcff,discount,presentValue,pv].every(finite))throw Error('AMD dated operating arithmetic exceeded the finite numerical range.');return {...r,...funding,ebit,tax,nopat,fcff,discountFactor:discount,pv:presentValue,cumulativeFCFF:cumulative,yearsFromOrigin,durationYears,periodEnd,derivedSalesCapital:funding.normalizedOperatingReinvestment!==0?(funding.fullFiscalRevenue-(index===0?d.anchor.revenue:index===1?d.annual[index-1].revenue+21789:d.annual[index-1].revenue))/funding.normalizedOperatingReinvestment:null};});
 const t=d.terminal,last=rows.at(-1),revenue=last.revenue*(1+t.growth),ebit=revenue*t.margin,nopat=ebit*(1-t.taxRate),reinvestment=nopat*t.growth/t.roic,p=selectedAmdCase(d).amdFundingPolicy,fundingFloor=revenue*(p.capex.at(-1)-p.depreciation.at(-1))+Math.max(0,revenue-last.revenue)*p.nwc;
 if(reinvestment+1e-8<fundingFloor)throw Error('AMD terminal g/ROIC investment is below physical and working-capital funding needs. Revise terminal assumptions.');
 const fcff=nopat-reinvestment,value=fcff/(t.wacc-t.growth),terminalPV=value/discount,enterprise=pv+terminalPV;
 if(![revenue,ebit,nopat,reinvestment,fcff,value,terminalPV,enterprise,fundingFloor].every(finite))throw Error('AMD dated operating arithmetic exceeded the finite numerical range.');
 const terminal={...t,revenue,ebit,nopat,reinvestment,fundingFloor,fcff,value,pv:terminalPV,discountFactor:discount,fcffGrowth:last.fcff!==0?fcff/last.fcff-1:null,revenueGrowthEndpointDifference:last.growth-t.growth};
 return {ticker:d.ticker,currency:d.currency,informationAsOf:d.informationAsOf,discountOrigin:d.discountOrigin,rows,terminal,forecastPV:pv,terminalPV,enterprise,terminalShare:enterprise>0?terminalPV/enterprise:null,peakEconomicDeficit:Math.max(0,-trough),negativeFCFFYears:rows.filter(r=>r.fcff<0).length,warnings:[incrementalRecord('AMD').prose.scope.en,incrementalRecord('AMD').prose.funding.en],classification:'Dated standalone operating EV before customer equity rebates and partner-asset flows.'};
}
